#define NULL 0

enum { MAP_LOC_LAST = 17, MAX_BEACHES_PER_LOC = 3, GAME_MODE_CAREER = 0 };

class FEMenuEntry {};
class PanelQuad { public: void TurnOn(bool); };
class PanelFile { public: void StartSlide(bool); };

class FEMenu
{
public:
	FEMenuEntry* current;
	virtual void setHigh(FEMenuEntry*, bool = true);
};

class FEMultiMenu : public FEMenu
{
public:
	virtual void OnActivate();
};

struct BFE_Location
{
	int levels[MAX_BEACHES_PER_LOC];
	int beaches[MAX_BEACHES_PER_LOC];
	bool all_levels_locked;
	bool all_beaches_locked;
	bool no_existing_levels;
};

class FEManager
{
public:
	int tmp_game_mode;
};

class FrontEndManager
{
public:
	bool return_to_fe;
	bool map_loading_screen;
};

extern FrontEndManager frontendmanager;

class BeachFrontEnd : public FEMultiMenu
{
public:
	bool in_career_mode;
	bool in_frontend;
	bool in_demo_mode;
	bool offset_set;
	int home_beach;
	int current_level_index;
	int goal_num[MAX_BEACHES_PER_LOC];
	FEMenuEntry* chall_text[MAX_BEACHES_PER_LOC];
	int current_beach_index;
	int current_location_index;
	BFE_Location locations[MAP_LOC_LAST];
	bool no_progress_path;
	PanelQuad* selected[64];
	PanelFile panel;
	bool sliding_in;
	FEManager* manager;

	void SetBeachData();
	void SetSecondaryCursor(FEMenuEntry*);
	void UpdateBeach(bool);
	void TurnBox(int, bool, float);
	void HideAllDots();
	void PrepareForLoading();
	virtual void PickDemo(int beach);
};

void BeachFrontEnd::PickDemo(int beach)
{
	in_career_mode = true;
	in_frontend = true;
	in_demo_mode = true;
/*	Save/load no longer part of map screen.  (dc 07/01/02)
	save_load->down = NULL;
*/
	offset_set = false;

	home_beach = -1;
	current_level_index = beach; //locations[current_location_index].levels[0];

	SetBeachData();

	FEMultiMenu::OnActivate();
	setHigh(current);
	SetSecondaryCursor(goal_num[0] != 0 ? chall_text[0] : NULL);
	if(in_frontend) 
	{
		UpdateBeach(false);
	}
	else //if(in_career_mode)
	{
		panel.StartSlide(sliding_in);
		TurnBox(current_beach_index, true, 0);	// we will call UpdateBeach after the slide-in (dc 04/27/02)
//		mem_lock_malloc(false);
//		g_game_ptr->play_movie("MAPROLL", true);
	}

//	StartFrontendFade();

	int l;
	for(l=0; l<MAP_LOC_LAST; l++)
	{
		int b;
		for(b=0; b<MAX_BEACHES_PER_LOC; b++)
			if(locations[l].levels[b] == current_level_index)
			{
				current_beach_index = locations[l].beaches[0];
				break;
			}

			if(b < MAX_BEACHES_PER_LOC)
				break;
	}
	current_location_index = l;

  no_progress_path = true;

  //SetProgressPath();

  // Turn off all blinking lights except for destination
	HideAllDots();

  // Turn on green destination dot
  if(selected[locations[current_location_index].beaches[0]]) selected[locations[current_location_index].beaches[0]]->TurnOn(true);

  frontendmanager.return_to_fe = false;
	frontendmanager.map_loading_screen = true;
	manager->tmp_game_mode = GAME_MODE_CAREER;
	PrepareForLoading();
}
